// Import of required libraries
import { test, expect, getBaseUrl, newSkyrampPlaywrightPage } from '@skyramp/skyramp';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

test.use({
    viewport: { width: 1280, height: 900 },
});

test('testUi', async ({ page }) => {
    test.setTimeout(94000);

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    const pageErrors: Error[] = [];
    page.on('pageerror', (error) => { pageErrors.push(error); });
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    await page.goto(baseUrl);
    await page.evaluate(() => { localStorage.setItem('excalidraw-state', JSON.stringify({ name: 'Sprint Notes<v3>|final' })); return localStorage.getItem('excalidraw-state'); });
    await page.goto(`${baseUrl}/?scenario=link-export`);
    await page.getByTestId("main-menu-trigger").click();
    await page.getByTestId("json-export-button").click();
    await expect(page.getByRole("button", { name: "Save to file" })).toBeDisabled();
    await expect(page.getByRole("button", { name: "Export to Link" })).toBeEnabled();
    await expect(page.getByRole("button", { name: "Export", exact: true })).toBeEnabled();
    expect(pageErrors).toHaveLength(0);
});
